1	import "server-only";
2	import { createPublicKey, verify as cryptoVerify } from "node:crypto";
3	import { getSetting, getSettingBool } from "./settings";
4	import { decryptSecret } from "./crypto-box";
5	
6	/**
7	 * Thin Discord REST + Interactions-verification layer for the Nxeon support
8	 * bridge (lib/discord-bridge.ts). Deliberately NOT a discord.js Gateway
9	 * client and NOT a long-running process: this bot only ever (a) makes plain
10	 * REST calls the platform's own server code triggers, and (b) answers
11	 * Discord's HTTP "Interactions Endpoint" POSTs (button clicks, modal
12	 * submits) via app/api/webhooks/discord/route.ts. See the research this
13	 * build executed: an HTTP-only bot is the right shape for this codebase's
14	 * existing poll/request-response architecture, and Discord forum channels
15	 * cannot have private threads anyway (irrelevant here since the bridge uses
16	 * plain text channels — see lib/discord-bridge.ts for that call).
17	 *
18	 * Every config value is read via getSetting/getSettingBool/decryptSecret —
19	 * NEVER a bare process.env.DISCORD_* — except as a secondary fallback
20	 * mirroring the exact convention lib/kb-llm.ts's resolveBotKey() already
21	 * established for kb_bot_api_key.
22	 */
23	
24	const DISCORD_API_BASE = "https://discord.com/api/v10";
25	
26	// ---------------------------------------------------------------------------
27	// Config
28	// ---------------------------------------------------------------------------
29	
30	export async function discordEnabled(): Promise<boolean> {
31	  return getSettingBool("discord_enabled", false);
32	}
33	
34	export async function discordApplicationId(): Promise<string> {
35	  const v = (await getSetting("discord_application_id", "")).trim();
36	  return v || (process.env.DISCORD_APPLICATION_ID ?? "").trim();
37	}
38	
39	export async function discordGuildId(): Promise<string> {
40	  const v = (await getSetting("discord_guild_id", "")).trim();
41	  return v || (process.env.DISCORD_GUILD_ID ?? "").trim();
42	}
43	
44	export async function discordPublicKey(): Promise<string> {
45	  const v = (await getSetting("discord_public_key", "")).trim();
46	  return v || (process.env.DISCORD_PUBLIC_KEY ?? "").trim();
47	}
48	
49	/** Decrypt-on-read, mirroring lib/kb-llm.ts's resolveBotKey() exactly. */
50	export async function discordBotToken(): Promise<string | null> {
51	  const enc = await getSetting("discord_bot_token", "");
52	  const own = decryptSecret(enc || null);
53	  if (own && own.trim()) return own.trim();
54	  const platform = process.env.DISCORD_BOT_TOKEN;
55	  return platform && platform.trim() ? platform.trim() : null;
56	}
57	
58	/** The configured Nxeon User.id Discord-originated replies attribute to. Empty = unset. */
59	export async function discordReplyAsUserId(): Promise<string> {
60	  return (await getSetting("discord_reply_as_user_id", "")).trim();
61	}
62	
63	// ---------------------------------------------------------------------------
64	// Ed25519 interaction-signature verification
65	// ---------------------------------------------------------------------------
66	
67	// The fixed 12-byte ASN.1 prefix for an Ed25519 SubjectPublicKeyInfo (SPKI)
68	// DER structure — "SEQUENCE { SEQUENCE { OID 1.3.101.112 } BIT STRING }".
69	// Discord (like most Ed25519 key issuers) hands out only the raw 32-byte
70	// public key as hex; Node's `crypto.createPublicKey` needs a full SPKI DER
71	// blob to build a KeyObject, and this prefix is constant for every Ed25519
72	// key, so prepending it to the raw 32 bytes reconstructs a valid SPKI DER
73	// value Node can parse. Verified against Node 22's `node:crypto` directly
74	// (generateKeyPairSync("ed25519") → export raw pub → reconstruct via this
75	// prefix → verify() succeeds and correctly rejects a tampered payload).
76	const ED25519_SPKI_DER_PREFIX = Buffer.from("302a300506032b6570032100", "hex");
77	
78	function ed25519PublicKeyFromHex(hex: string) {
79	  const raw = Buffer.from(hex, "hex");
80	  if (raw.length !== 32) throw new Error(`Discord public key must decode to 32 bytes, got ${raw.length}`);
81	  return createPublicKey({
82	    key: Buffer.concat([ED25519_SPKI_DER_PREFIX, raw]),
83	    format: "der",
84	    type: "spki",
85	  });
86	}
87	
88	/**
89	 * Verify a Discord Interactions Endpoint request. Discord signs
90	 * `timestamp + rawBody` with Ed25519 and sends the signature + timestamp as
91	 * headers; this MUST be checked against the raw (pre-JSON-parse) request body
92	 * before trusting anything in it. Returns false on ANY problem (missing
93	 * headers, malformed hex, wrong-length key, bad signature, tampered body) —
94	 * never throws, so callers can treat "false" as the single "reject with 401"
95	 * signal.
96	 */
97	export function verifyDiscordSignature(args: {
98	  rawBody: string;
99	  signature: string | null | undefined;
100	  timestamp: string | null | undefined;
101	  publicKeyHex: string;
102	}): boolean {
103	  const { rawBody, signature, timestamp, publicKeyHex } = args;
104	  if (!signature || !timestamp || !publicKeyHex) return false;
105	  try {
106	    if (!/^[0-9a-f]+$/i.test(signature) || !/^[0-9a-f]+$/i.test(publicKeyHex)) return false;
107	    const key = ed25519PublicKeyFromHex(publicKeyHex);
108	    const message = Buffer.from(timestamp + rawBody, "utf8");
109	    const sig = Buffer.from(signature, "hex");
110	    return cryptoVerify(null, message, key, sig);
111	  } catch {
112	    return false;
113	  }
114	}
115	
116	// ---------------------------------------------------------------------------
117	// REST client
118	// ---------------------------------------------------------------------------
119	
120	export class DiscordApiError extends Error {
121	  constructor(
122	    public status: number,
123	    public body: unknown,
124	  ) {
125	    super(`Discord API ${status}: ${typeof body === "string" ? body : JSON.stringify(body)}`);
126	  }
127	}
128	
129	/**
130	 * Bot-authenticated REST call. Respects a single 429 retry (Discord's rate
131	 * limits are generous at this volume — 50 req/s global — so anything beyond
132	 * one retry would indicate a real problem, not routine throttling). Returns
133	 * `null` (never throws) when the bot token isn't configured, so every caller
134	 * in lib/discord-bridge.ts can stay a best-effort no-op.
135	 */
136	export async function discordFetch(
137	  path: string,
138	  init: { method?: string; body?: unknown; retried?: boolean } = {},
139	): Promise<{ status: number; json: unknown } | null> {
140	  const token = await discordBotToken();
141	  if (!token) {
142	    console.error("[discord] no bot token configured — cannot call", path);
143	    return null;
144	  }
145	  const res = await fetch(`${DISCORD_API_BASE}${path}`, {
146	    method: init.method ?? "GET",
147	    headers: {
148	      Authorization: `Bot ${token}`,
149	      "Content-Type": "application/json",
150	    },
151	    body: init.body !== undefined ? JSON.stringify(init.body) : undefined,
152	  });
153	
154	  if (res.status === 429 && !init.retried) {
155	    const retryAfterSec = Number(res.headers.get("Retry-After") ?? "1") || 1;
156	    await new Promise((r) => setTimeout(r, Math.min(retryAfterSec, 5) * 1000));
157	    return discordFetch(path, { ...init, retried: true });
158	  }
159	
160	  const text = await res.text();
161	  let json: unknown = null;
162	  if (text) {
163	    try {
164	      json = JSON.parse(text);
165	    } catch {
166	      json = text;
167	    }
168	  }
169	  return { status: res.status, json };
170	}
171	
172	// ---------------------------------------------------------------------------
173	// Typed helpers
174	// ---------------------------------------------------------------------------
175	
176	/** Discord channel type 0 = GUILD_TEXT. */
177	const GUILD_TEXT_CHANNEL_TYPE = 0;
178	
179	export async function createGuildTextChannel(name: string, topic?: string): Promise<string | null> {
180	  const guildId = await discordGuildId();
181	  if (!guildId) {
182	    console.error("[discord] no guild id configured — cannot create channel");
183	    return null;
184	  }
185	  // Discord channel names: lowercase, hyphens, max 100 chars, no spaces.
186	  const safeName = name
187	    .toLowerCase()
188	    .replace(/[^a-z0-9-]+/g, "-")
189	    .replace(/-+/g, "-")
190	    .replace(/^-|-$/g, "")
191	    .slice(0, 90) || "ticket";
192	
193	  const res = await discordFetch(`/guilds/${guildId}/channels`, {
194	    method: "POST",
195	    body: {
196	      name: safeName,
197	      type: GUILD_TEXT_CHANNEL_TYPE,
198	      topic: topic?.slice(0, 1024),
199	    },
200	  });
201	  if (!res || res.status >= 300) {
202	    console.error("[discord] createGuildTextChannel failed", res?.status, res?.json);
203	    return null;
204	  }
205	  return (res.json as { id: string }).id;
206	}
207	
208	/** A button (type 2) inside a single action row (type 1), Reply style. */
209	function replyButtonRow(customId: string, label = "Reply"): unknown {
210	  return {
211	    type: 1,
212	    components: [{ type: 2, style: 1, label, custom_id: customId }],
213	  };
214	}
215	
216	/** Post a plain message, optionally with a Reply button. */
217	export async function postChannelMessage(
218	  channelId: string,
219	  content: string,
220	  opts: { replyButtonCustomId?: string } = {},
221	): Promise<boolean> {
222	  const res = await discordFetch(`/channels/${channelId}/messages`, {
223	    method: "POST",
224	    body: {
225	      content: content.slice(0, 2000), // Discord message content cap
226	      components: opts.replyButtonCustomId ? [replyButtonRow(opts.replyButtonCustomId)] : undefined,
227	    },
228	  });
229	  if (!res || res.status >= 300) {
230	    console.error("[discord] postChannelMessage failed", channelId, res?.status, res?.json);
231	    return false;
232	  }
233	  return true;
234	}
235	
236	export async function getChannel(channelId: string): Promise<{ id: string; name: string } | null> {
237	  const res = await discordFetch(`/channels/${channelId}`);
238	  if (!res || res.status >= 300) return null;
239	  return res.json as { id: string; name: string };
240	}
241	
242	export async function deleteChannel(channelId: string): Promise<boolean> {
243	  const res = await discordFetch(`/channels/${channelId}`, { method: "DELETE" });
244	  return Boolean(res && res.status < 300);
245	}
246	
247	// ---------------------------------------------------------------------------
248	// Interaction response helpers (used by app/api/webhooks/discord/route.ts)
249	// ---------------------------------------------------------------------------
250	
251	/** Interaction type constants (Discord API v10). */
252	export const InteractionType = {
253	  PING: 1,
254	  APPLICATION_COMMAND: 2,
255	  MESSAGE_COMPONENT: 3,
256	  APPLICATION_COMMAND_AUTOCOMPLETE: 4,
257	  MODAL_SUBMIT: 5,
258	} as const;
259	
260	/** Interaction callback type constants. */
261	export const InteractionCallbackType = {
262	  PONG: 1,
263	  CHANNEL_MESSAGE_WITH_SOURCE: 4,
264	  MODAL: 9,
265	} as const;
266	
267	/** Build the modal-open response body for a "Reply" button click. */
268	export function replyModalResponse(customId: string, title = "Reply to customer") {
269	  return {
270	    type: InteractionCallbackType.MODAL,
271	    data: {
272	      custom_id: customId,
273	      title,
274	      components: [
275	        {
276	          type: 1,
277	          components: [
278	            {
279	              type: 4, // TEXT_INPUT
280	              custom_id: "reply_text",
281	              style: 2, // paragraph
282	              label: "Your reply",
283	              required: true,
284	              max_length: 4000,
285	            },
286	          ],
287	        },
288	      ],
289	    },
290	  };
291	}
292	
293	/** Build a simple, visible channel-message acknowledgement response body. */
294	export function channelMessageResponse(content: string) {
295	  return {
296	    type: InteractionCallbackType.CHANNEL_MESSAGE_WITH_SOURCE,
297	    data: { content: content.slice(0, 2000) },
298	  };
299	}
300	
301	/** Extract the single text-input value from a MODAL_SUBMIT interaction payload. */
302	export function extractModalText(interaction: unknown): string {
303	  try {
304	    const data = (interaction as { data?: { components?: unknown[] } }).data;
305	    const row = data?.components?.[0] as { components?: { value?: unknown }[] } | undefined;
306	    const value = row?.components?.[0]?.value;
307	    return typeof value === "string" ? value : "";
308	  } catch {
309	    return "";
310	  }
311	}
