1	import "server-only";
2	import { db } from "./db";
3	import {
4	  discordEnabled,
5	  discordReplyAsUserId,
6	  createGuildTextChannel,
7	  postChannelMessage,
8	} from "./discord";
9	import { writeTicketReply, writeChatReply } from "./reply-core";
10	
11	/**
12	 * Nxeon Discord support bridge — Phase 1 (mirror) + a deliberately simplified
13	 * Phase 2 (reply round-trip), scoped to the owner's OWN PERSONAL USE right now
14	 * (get a phone push notification when a ticket/chat comes in; reply from
15	 * Discord and have it really reach the customer). NOT the eventual multi-staff
16	 * version — there is no Discord-account-to-Nxeon-user identity linking here,
17	 * on purpose; that's deferred until real support staff join.
18	 *
19	 * SHAPE: one plain text channel per ticket / chat conversation in a single,
20	 * private guild ("Nxeon Cloud", one member: the owner). Text channel, not a
21	 * forum-with-threads: forum channels cannot have PRIVATE threads in Discord's
22	 * current API, and since this whole guild is private and single-member,
23	 * "private within the guild" isn't a requirement anyway — a plain channel per
24	 * ticket is simpler to create/list/delete via REST and needs no thread
25	 * bookkeeping. See lib/discord.ts for the REST client and Ed25519 signature
26	 * verification, and app/api/webhooks/discord/route.ts for the Interactions
27	 * Endpoint that handles the Reply button + modal.
28	 *
29	 * ATTRIBUTION, NOT AUTHENTICATION. `submitDiscordReply` below attributes every
30	 * Discord-originated reply to the single Nxeon User.id configured in the
31	 * `discord_reply_as_user_id` setting. That is a deliberate simplification: the
32	 * real access control is Discord's own guild membership (only the owner is in
33	 * this private guild) plus this webhook's Ed25519 signature verification
34	 * (nothing reaches this code without both). There is no second staff member to
35	 * distinguish yet, so a single configured user id is the whole "who is this"
36	 * question this build needs to answer. When actual support staff join later,
37	 * this is the seam to replace with real per-Discord-user identity linking —
38	 * do NOT bolt that on here without designing it properly.
39	 *
40	 * KILL-SWITCH DISCIPLINE: every exported function below checks
41	 * `discordEnabled()` FIRST and returns silently if it's off, and every DB/REST
42	 * call is wrapped so a Discord outage or misconfiguration can NEVER throw back
43	 * into a ticket/chat write path — matching this codebase's established
44	 * best-effort third-party-integration pattern (see how `sendMail` failures are
45	 * handled in lib/reply-core.ts).
46	 *
47	 * SCHEMA CAVEAT: `Ticket.discordThreadId` / `ChatConversation.discordThreadId`
48	 * are NOT YET pushed to the live database (see the doc comments on those
49	 * fields in prisma/schema.prisma) — every read/write of them here goes through
50	 * an explicit `as any`/unchecked cast until a real `prisma db push` +
51	 * `generate` runs for this branch.
52	 */
53	
54	const APP_URL = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
55	
56	// ---------------------------------------------------------------------------
57	// custom_id encoding — shared vocabulary between the message Reply button, the
58	// modal opened in response to it, and the webhook route that parses both.
59	// ---------------------------------------------------------------------------
60	
61	export type BridgeKind = "ticket" | "chat";
62	
63	function isBridgeKind(v: string): v is BridgeKind {
64	  return v === "ticket" || v === "chat";
65	}
66	
67	export function replyButtonCustomId(kind: BridgeKind, id: string): string {
68	  return `dc_reply:${kind}:${id}`;
69	}
70	
71	export function replyModalCustomId(kind: BridgeKind, id: string): string {
72	  return `dc_reply_modal:${kind}:${id}`;
73	}
74	
75	/** Parse a `dc_reply:<kind>:<id>` or `dc_reply_modal:<kind>:<id>` custom_id. */
76	export function parseBridgeCustomId(
77	  customId: string,
78	): { action: "reply" | "reply_modal"; kind: BridgeKind; id: string } | null {
79	  const parts = customId.split(":");
80	  if (parts.length !== 3) return null;
81	  const [prefix, kindRaw, id] = parts;
82	  if (!id) return null;
83	  if (!isBridgeKind(kindRaw)) return null;
84	  if (prefix === "dc_reply") return { action: "reply", kind: kindRaw, id };
85	  if (prefix === "dc_reply_modal") return { action: "reply_modal", kind: kindRaw, id };
86	  return null;
87	}
88	
89	// ---------------------------------------------------------------------------
90	// Ticket mirror
91	// ---------------------------------------------------------------------------
92	
93	type TicketForChannel = { id: string; subject: string; priority: string; userId: string };
94	
95	/** Create the ticket's Discord channel + post the opening context message if
96	 *  it doesn't have one yet; return the (existing or new) channel id. */
97	async function ensureTicketChannel(ticket: TicketForChannel & { discordThreadId?: string | null }): Promise<string | null> {
98	  const existing = (ticket as { discordThreadId?: string | null }).discordThreadId;
99	  if (existing) return existing;
100	
101	  const user = await db.user.findUnique({ where: { id: ticket.userId }, select: { name: true, email: true } });
102	  const channelId = await createGuildTextChannel(
103	    `ticket-${ticket.id.slice(-8)}`,
104	    `Ticket ${ticket.id}: ${ticket.subject}`.slice(0, 1024),
105	  );
106	  if (!channelId) return null;
107	
108	  await postChannelMessage(
109	    channelId,
110	    [
111	      "🎫 **New support ticket**",
112	      `**Subject:** ${ticket.subject}`,
113	      `**Priority:** ${ticket.priority}`,
114	      `**Customer:** ${user?.name ?? "?"}${user?.email ? ` (${user.email})` : ""}`,
115	      `**Admin:** ${APP_URL}/admin/support/${ticket.id}`,
116	    ].join("\n"),
117	  );
118	
119	  await db.ticket.update({ where: { id: ticket.id }, data: { discordThreadId: channelId } as any });
120	  return channelId;
121	}
122	
123	/** Mirror a brand-new ticket (called right after `db.ticket.create`). */
124	export async function mirrorNewTicketToDiscord(ticketId: string): Promise<void> {
125	  if (!(await discordEnabled())) return;
126	  try {
127	    const ticket = await db.ticket.findUnique({
128	      where: { id: ticketId },
129	      include: { messages: { orderBy: { createdAt: "asc" }, take: 1 } },
130	    });
131	    if (!ticket) return;
132	    const channelId = await ensureTicketChannel(ticket);
133	    if (!channelId) return;
134	    const firstMessage = ticket.messages[0];
135	    if (firstMessage) {
136	      await postChannelMessage(channelId, `👤 **Customer:** ${firstMessage.body}`, {
137	        replyButtonCustomId: replyButtonCustomId("ticket", ticket.id),
138	      });
139	    }
140	  } catch (e) {
141	    console.error("[discord-bridge] mirrorNewTicketToDiscord failed (non-fatal)", ticketId, e);
142	  }
143	}
144	
145	/** Mirror a reply on an EXISTING ticket (staff or customer) into its channel,
146	 *  creating the channel first if this ticket predates the bridge (or its
147	 *  earlier mirror attempt failed). */
148	export async function mirrorTicketReplyToDiscord(ticketId: string, body: string, isStaffMessage: boolean): Promise<void> {
149	  if (!(await discordEnabled())) return;
150	  try {
151	    const ticket = await db.ticket.findUnique({ where: { id: ticketId } });
152	    if (!ticket) return;
153	    const channelId = await ensureTicketChannel(ticket);
154	    if (!channelId) return;
155	    const label = isStaffMessage ? "🛟 **Staff**" : "👤 **Customer**";
156	    await postChannelMessage(channelId, `${label}: ${body}`, {
157	      replyButtonCustomId: replyButtonCustomId("ticket", ticketId),
158	    });
159	  } catch (e) {
160	    console.error("[discord-bridge] mirrorTicketReplyToDiscord failed (non-fatal)", ticketId, e);
161	  }
162	}
163	
164	// ---------------------------------------------------------------------------
165	// Chat mirror
166	// ---------------------------------------------------------------------------
167	
168	type ConvoForChannel = { id: string; name: string | null; email: string | null; userId: string | null };
169	
170	async function ensureChatChannel(convo: ConvoForChannel & { discordThreadId?: string | null }): Promise<string | null> {
171	  const existing = (convo as { discordThreadId?: string | null }).discordThreadId;
172	  if (existing) return existing;
173	
174	  const who = convo.name
175	    ? `${convo.name}${convo.email ? ` (${convo.email})` : ""}`
176	    : convo.email || "Anonymous visitor";
177	  const channelId = await createGuildTextChannel(
178	    `chat-${convo.id.slice(-8)}`,
179	    `Live chat ${convo.id}: ${who}`.slice(0, 1024),
180	  );
181	  if (!channelId) return null;
182	
183	  await postChannelMessage(
184	    channelId,
185	    [
186	      "💬 **New live chat conversation**",
187	      `**Visitor:** ${who}`,
188	      `**Signed-in customer:** ${convo.userId ? "yes" : "no"}`,
189	      `**Admin inbox:** ${APP_URL}/admin/chat`,
190	    ].join("\n"),
191	  );
192	
193	  await db.chatConversation.update({ where: { id: convo.id }, data: { discordThreadId: channelId } as any });
194	  return channelId;
195	}
196	
197	/** Mirror one chat message (visitor OR agent) — handles both "first message of
198	 *  a new conversation" (creates the channel) and "message in an existing
199	 *  conversation" (posts into it) via the same discordThreadId check. */
200	export async function mirrorChatMessageToDiscord(
201	  conversationId: string,
202	  body: string,
203	  sender: "visitor" | "agent",
204	): Promise<void> {
205	  if (!(await discordEnabled())) return;
206	  try {
207	    const convo = await db.chatConversation.findUnique({ where: { id: conversationId } });
208	    if (!convo) return;
209	    const channelId = await ensureChatChannel(convo);
210	    if (!channelId) return;
211	    const label = sender === "agent" ? "🛟 **Staff**" : "👤 **Visitor**";
212	    await postChannelMessage(channelId, `${label}: ${body}`, {
213	      replyButtonCustomId: replyButtonCustomId("chat", conversationId),
214	    });
215	  } catch (e) {
216	    console.error("[discord-bridge] mirrorChatMessageToDiscord failed (non-fatal)", conversationId, e);
217	  }
218	}
219	
220	// ---------------------------------------------------------------------------
221	// Reply round-trip (Discord → Nxeon) — called by the modal-submit handler in
222	// app/api/webhooks/discord/route.ts. Returns the text to show back in Discord
223	// as the interaction's visible acknowledgement message.
224	// ---------------------------------------------------------------------------
225	
226	const NOT_CONFIGURED_MSG =
227	  "⚠️ Discord replies aren't configured yet — set discord_reply_as_user_id in admin settings";
228	
229	export async function submitDiscordReply(kind: BridgeKind, id: string, replyText: string): Promise<string> {
230	  const text = replyText.trim();
231	  if (!text) return "⚠️ Empty reply — nothing sent.";
232	
233	  const replyAsUserId = await discordReplyAsUserId();
234	  if (!replyAsUserId) {
235	    console.error("[discord-bridge] reply attempted with discord_reply_as_user_id unset", { kind, id });
236	    return NOT_CONFIGURED_MSG;
237	  }
238	
239	  try {
240	    if (kind === "ticket") {
241	      const result = await writeTicketReply({
242	        actorId: replyAsUserId,
243	        actorIsSupportStaff: true,
244	        ticketId: id,
245	        body: text,
246	      });
247	      if (result.error) return `⚠️ ${result.error}`;
248	      return "✅ Reply sent to the customer.";
249	    }
250	
251	    const result = await writeChatReply({ conversationId: id, body: text, staffId: replyAsUserId });
252	    if (result.error) return `⚠️ ${result.error}`;
253	    return "✅ Reply sent to the customer.";
254	  } catch (e) {
255	    console.error("[discord-bridge] submitDiscordReply failed", kind, id, e);
256	    return "⚠️ Something went wrong sending that reply — check the admin panel.";
257	  }
258	}
