14	/**
15	 * Discord "Interactions Endpoint" webhook — the reply half of the support
16	 * bridge (see lib/discord-bridge.ts's top-of-file comment for the full
17	 * picture). Handles exactly three interaction shapes:
18	 *
19	 *   1. PING (type 1)              → PONG. Discord requires this before it will
20	 *                                    even save this URL in the Developer
21	 *                                    Portal, and it periodically re-sends PINGs
22	 *                                    (plus deliberately-invalid signatures) to
23	 *                                    keep testing the endpoint.
24	 *   2. MESSAGE_COMPONENT (type 3) → the "Reply" button under a mirrored
25	 *                                    message. Responds by opening a MODAL
26	 *                                    (type 9) — Discord requires the modal to
27	 *                                    be opened as the DIRECT response to the
28	 *                                    button click, not a follow-up call.
29	 *   3. MODAL_SUBMIT (type 5)      → the reply text the owner typed. Writes it
30	 *                                    through the shared reply-writing core
31	 *                                    (lib/reply-core.ts) and acknowledges with
32	 *                                    a visible confirmation/error message.
33	 *
34	 * Signature verification mirrors app/api/stripe/webhook/route.ts's pattern:
35	 * read the RAW body as text before any JSON parsing, verify a signature
36	 * header (Ed25519 here, HMAC there), and reject with a 4xx on any failure —
37	 * this is SECURITY CRITICAL. Every other interaction shape (slash commands,
38	 * autocomplete, …) is currently unused and gets a generic ack rather than an
39	 * error, since Discord expects SOME response.
40	 */
41	export async function POST(req: Request) {
42	  const rawBody = await req.text();
43	  const signature = req.headers.get("X-Signature-Ed25519");
44	  const timestamp = req.headers.get("X-Signature-Timestamp");
45	  const publicKeyHex = await discordPublicKey();
46	
47	  if (!publicKeyHex) {
48	    console.error("[discord-webhook] no discord_public_key configured — rejecting");
49	    return NextResponse.json({ error: "not configured" }, { status: 401 });
50	  }
51	
52	  const valid = verifyDiscordSignature({ rawBody, signature, timestamp, publicKeyHex });
53	  if (!valid) {
54	    return NextResponse.json({ error: "invalid request signature" }, { status: 401 });
55	  }
56	
57	  let interaction: Record<string, unknown>;
58	  try {
59	    interaction = JSON.parse(rawBody);
60	  } catch {
61	    return NextResponse.json({ error: "invalid body" }, { status: 400 });
62	  }
63	
64	  const type = interaction.type as number | undefined;
65	
66	  // 1. PING — must be answered exactly like this or Discord refuses to save
67	  // the endpoint URL in the Developer Portal.
68	  if (type === InteractionType.PING) {
69	    return NextResponse.json({ type: 1 });
70	  }
71	
72	  // 2. Button click ("Reply") — open the reply modal.
73	  if (type === InteractionType.MESSAGE_COMPONENT) {
74	    const customId = (interaction.data as { custom_id?: string } | undefined)?.custom_id ?? "";
75	    const parsed = parseBridgeCustomId(customId);
76	    if (!parsed || parsed.action !== "reply") {
77	      return NextResponse.json(channelMessageResponse("Unrecognized button."));
78	    }
79	    return NextResponse.json(replyModalResponse(replyModalCustomId(parsed.kind, parsed.id)));
80	  }
81	
82	  // 3. Modal submit — the owner's typed reply.
83	  if (type === InteractionType.MODAL_SUBMIT) {
84	    const customId = (interaction.data as { custom_id?: string } | undefined)?.custom_id ?? "";
85	    const parsed = parseBridgeCustomId(customId);
86	    if (!parsed || parsed.action !== "reply_modal") {
87	      return NextResponse.json(channelMessageResponse("Unrecognized submission."));
88	    }
89	    const text = extractModalText(interaction);
90	    const ackText = await submitDiscordReply(parsed.kind, parsed.id, text);
91	    return NextResponse.json(channelMessageResponse(ackText));
92	  }
93	
94	  // Any other interaction type (slash commands, autocomplete, …): none are
95	  // registered by this bridge, but Discord still expects a response.
96	  return NextResponse.json(channelMessageResponse("This interaction isn't handled."));
97	}
