40	/** Write a ticket reply. Mirrors `replyTicket`'s exact prior DB-write body. */
41	export async function writeTicketReply(args: {
42	  /** The id of the user the message is authored as (TicketMessage.authorId). */
43	  actorId: string;
44	  /** Whether the calling actor is support staff (before the same-ticket-owner override below). */
45	  actorIsSupportStaff: boolean;
46	  ticketId: string;
47	  body: string;
48	}): Promise<{ error?: string; isStaff?: boolean; ticketUserId?: string; subject?: string }> {
49	  const body = args.body.trim();
50	  if (body.length < 2 || body.length > 10000) return { error: "Message too short." };
51	
52	  const ticket = await db.ticket.findUnique({ where: { id: args.ticketId } });
53	  if (!ticket) return { error: "Ticket not found." };
54	  // A staff member replying to their OWN ticket (as its customer) is not a
55	  // "staff reply" — exactly the same override the original action applied.
56	  const isStaff = args.actorIsSupportStaff && ticket.userId !== args.actorId;
57	  if (ticket.userId !== args.actorId && !args.actorIsSupportStaff) return { error: "Forbidden." };
58	
59	  await db.$transaction([
60	    db.ticketMessage.create({ data: { ticketId: args.ticketId, body, authorId: args.actorId, isStaff } }),
61	    db.ticket.update({
62	      where: { id: args.ticketId },
63	      data: { status: isStaff ? "ANSWERED" : "CUSTOMER_REPLY" },
64	    }),
65	  ]);
66	
67	  if (isStaff) {
68	    await db.notification.create({
69	      data: {
70	        userId: ticket.userId,
71	        title: `Support replied: ${ticket.subject}`,
72	        href: `/dashboard/support/${args.ticketId}`,
73	      },
74	    });
75	    // Also EMAIL the customer the staff reply — an in-app bell alone is easy to
76	    // miss. Best-effort: a mail failure must never fail the reply itself.
77	    try {
78	      const customer = await db.user.findUnique({ where: { id: ticket.userId }, select: { email: true } });
79	      if (customer?.email) {
80	        const tpl = emails.ticketReply({
81	          ticketId: args.ticketId,
82	          subject: ticket.subject,
83	          replyPreview: body,
84	        });
85	        await sendMail({
86	          to: customer.email,
87	          subject: tpl.subject,
88	          html: tpl.html,
89	          template: tpl.template,
90	          userId: ticket.userId,
91	          kind: "support_reply",
92	        });
93	      }
94	    } catch (e) {
95	      console.error("[support] staff-reply email failed (non-fatal)", e);
96	    }
97	  } else {
98	    const admins = await db.user.findMany({ where: { role: "ADMIN" } });
99	    await db.notification.createMany({
100	      data: admins.map((a) => ({
101	        userId: a.id,
102	        title: `Ticket reply: ${ticket.subject}`,
103	        href: `/admin/support/${args.ticketId}`,
104	      })),
105	    });
106	  }
107	
108	  return { isStaff, ticketUserId: ticket.userId, subject: ticket.subject };
109	}
