111	/** Write a chat reply. Mirrors `replyToConversation`'s exact prior DB-write body. */
112	export async function writeChatReply(args: {
113	  conversationId: string;
114	  body: string;
115	  /** The staff/admin user id the reply is attributed to (assignedToId). */
116	  staffId: string;
117	}): Promise<{ error?: string; ok?: boolean; conversationUserId?: string | null }> {
118	  const parsed = z
119	    .object({ id: z.string().min(1), body: z.string().trim().min(1).max(5000) })
120	    .safeParse({ id: args.conversationId, body: args.body });
121	  if (!parsed.success) return { error: "Message must be between 1 and 5000 characters." };
122	
123	  const convo = await db.chatConversation.findUnique({ where: { id: parsed.data.id } });
124	  if (!convo) return { error: "Conversation not found." };
125	
126	  await db.$transaction([
127	    db.chatMessage.create({
128	      data: { conversationId: parsed.data.id, sender: "agent", body: parsed.data.body },
129	    }),
130	    db.chatConversation.update({
131	      where: { id: parsed.data.id },
132	      data: {
133	        status: "OPEN",
134	        unreadForUser: true,
135	        unreadForAgent: false,
136	        assignedToId: args.staffId,
137	        lastMessageAt: new Date(),
138	      },
139	    }),
140	  ]);
141	
142	  // If the visitor is a signed-in customer, drop them a notification.
143	  if (convo.userId) {
144	    await db.notification
