146	        data: {
147	          userId: convo.userId,
148	          title: "New reply in your live chat",
149	          href: "/dashboard",
150	        },
151	      })
152	      .catch(() => {});
153	  }
154	
155	  return { ok: true, conversationUserId: convo.userId };
