70	/**
71	 * Is the OAuth client registered in this environment? When false the UI hides
72	 * the "Connect Cloudflare" button and falls back to the paste-a-token path, so
73	 * nothing breaks before the owner registers the client in their dashboard.
74	 */
75	export function cloudflareOauthConfigured(): boolean {
76	  return Boolean(
77	    (process.env.CLOUDFLARE_OAUTH_CLIENT_ID ?? "").trim() &&
78	      (process.env.CLOUDFLARE_OAUTH_CLIENT_SECRET ?? "").trim(),
79	  );
80	}
