249	/** Exchange an authorization code (with the PKCE verifier) for credentials. */
250	export async function cfExchangeCode(opts: {
251	  code: string;
252	  codeVerifier: string;
253	}): Promise<{ creds?: CfOauthCreds; error?: string }> {
254	  return tokenRequest({
255	    grant_type: "authorization_code",
256	    code: opts.code,
257	    redirect_uri: cfRedirectUri(),
258	    code_verifier: opts.codeVerifier,
259	  });
260	}
261	
262	/** Trade a refresh token for a fresh access token. */
263	export async function cfRefresh(refreshToken: string): Promise<{ creds?: CfOauthCreds; error?: string }> {
264	  return tokenRequest({ grant_type: "refresh_token", refresh_token: refreshToken });
265	}
