267	/**
268	 * Best-effort revoke at Cloudflare so disconnecting here also drops their side.
269	 * Never throws and never blocks the local disconnect.
270	 */
271	export async function cfRevoke(token: string): Promise<void> {
272	  if (SANDBOX || !cloudflareOauthConfigured()) return;
273	  try {
274	    await fetch(CF_OAUTH_REVOKE_URL, {
275	      method: "POST",
276	      headers: { "Content-Type": "application/x-www-form-urlencoded" },
277	      body: new URLSearchParams({
278	        token,
279	        client_id: (process.env.CLOUDFLARE_OAUTH_CLIENT_ID ?? "").trim(),
280	        client_secret: (process.env.CLOUDFLARE_OAUTH_CLIENT_SECRET ?? "").trim(),
281	      }).toString(),
282	      cache: "no-store",
283	    });
284	  } catch {
285	    // Local disconnect is authoritative for us — ignore a failed remote revoke.
286	  }
287	}
