import { readFileSync } from "node:fs";
import { join } from "node:path";
import { stripComments, stripCommentsAndStrings } from "./_source-tools.ts";

/**
 * Structural guards over the CUSTOMER-FACING SERVER ACTIONS.
 *
 * These are the functions the portal calls to act on a customer's behalf, and
 * they are the widest attack surface in the product for one reason that is easy
 * to forget while reading them: **every export of a `"use server"` file is a
 * public network endpoint**. Not "callable from the page that imports it" —
 * callable by a stranger with curl. That property is what turned
 * `verifyTotpForUser` into an unauthenticated 2FA brute-force oracle
 * (QA-PRELAUNCH P0-2) and is why `lib/safe-next.ts` and `lib/totp-verify.ts`
 * exist as plain modules.
 *
 * A reviewer can hold that in their head for one file. Nobody holds it for
 * fifteen, forever, while adding a sixteenth. So it is asserted here instead.
 *
 * ── WHY THE SOURCE IS STRIPPED OF COMMENTS FIRST ─────────────────────────────
 * This codebase documents its incidents in the code, at length. A tripwire that
 * greps raw source for `assertNotImpersonating` matches the comment explaining
 * why the guard matters — so it passes on a function whose guard was deleted and
 * whose comment survived, which is the exact edit a careless refactor makes.
 * `stripComments` removes comments (and only comments) before anything is
 * matched, so every assertion below is about executable code.
 */

const LIB = join(import.meta.dirname, "..", "lib");

/* ------------------------------------------------------------------ *
 * Source utilities
 * ------------------------------------------------------------------ */

/**
 * Remove `//` and slash-star comments while preserving string and template
 * literals verbatim (a `"https://…"` is not a comment, and neither is the `//`
 * inside `/^https?:\/\//`). Replaces each comment with a single space so token
 * boundaries survive.
 */


function source(file: string): string {
  return stripComments(readFileSync(join(LIB, file), "utf8"));
}

