import { test } from "node:test";
import assert from "node:assert/strict";
import { randomUUID } from "node:crypto";
import { readFileSync, readdirSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { trustedClientIp, toolRateLimitByIp, UNKNOWN_IP } from "../app/api/_lib/client-ip.ts";
import { PRIVATE_NO_STORE, NO_STORE_HEADERS } from "../app/api/_lib/no-store.ts";

/**
 * Tripwires for the 2026-07-27 HTTP API surface audit.
 *
 * Two defect classes, both confirmed against the running production server
 * before they were fixed:
 *
 *   1. Every per-IP rate limit keyed on the FIRST hop of `X-Forwarded-For`.
 *      nginx is configured with `$proxy_add_x_forwarded_for`, which APPENDS the
 *      real peer, so the first hop is whatever the caller typed. Proven live:
 *        curl -H 'X-Forwarded-For: 203.0.113.77' https://nxeon.cloud/api/tools/my-ip
 *        → {"ip":"203.0.113.77","forwardedFor":"203.0.113.77, 127.0.0.1"}
 *      One header per request bought an unlimited budget on every throttled
 *      endpoint, including the ones that spend money (Claude, the registrar).
 *
 *   2. Per-customer and credential-bearing JSON went out with NO `Cache-Control`
 *      at all, which lets a shared cache assign heuristic freshness (RFC 9111
 *      §4.2.2) and replay one caller's body to the next.
 *
 * Deterministic: no network, no DB, no clock. Nothing here imports a route
 * module — that would pull in Prisma and open a connection to the production
 * database — so the cache-header checks assert against route SOURCE instead.
 */

const HERE = path.dirname(fileURLToPath(import.meta.url));
const API_DIR = path.join(HERE, "..", "app", "api");

function req(headers: Record<string, string>): Request {
  return new Request("https://nxeon.cloud/api/tools/my-ip", { headers });
}

// ───────────────────────────────────────────────────────────────────────────
// 1. trustedClientIp — never returns a caller-controlled value
// ───────────────────────────────────────────────────────────────────────────

test("the spoofed first XFF hop is ignored; the nginx-appended last hop wins", () => {
  // Exactly the header production returned during the audit.
  const ip = trustedClientIp(req({ "x-forwarded-for": "203.0.113.77, 51.79.162.96" }));
  assert.equal(ip, "51.79.162.96");
  assert.notEqual(ip, "203.0.113.77", "the attacker-chosen hop must never be the key");
});

