 * This bridge only ever operates inside ONE guild, so a guild interaction's
 * `member.user.id` is the field that is actually always present — `user.id`
 * (top-level) is Discord's DM-interaction shape and would be undefined here,
 * but is checked as a harmless fallback in case that ever changes. Both
 * fields are sent and Ed25519-signed by Discord itself (verified by
 * `verifyDiscordSignature` BEFORE this is ever called), so once signature
 * verification has passed, this id is trustworthy — it cannot be spoofed by
 * the Discord user who clicked the button.
 */
export function extractInteractionUserId(interaction: unknown): string | null {
  try {
    const i = interaction as { member?: { user?: { id?: unknown } }; user?: { id?: unknown } };
    const guildUserId = i.member?.user?.id;
    if (typeof guildUserId === "string" && guildUserId) return guildUserId;
    const dmUserId = i.user?.id;
    if (typeof dmUserId === "string" && dmUserId) return dmUserId;
    return null;
  } catch {
    return null;
  }
}

