import "server-only";

/**
 * Discord OAuth2 (Authorization Code grant, `identify` scope only) for the
 * staff Discord-account-linking flow — see
 * app/api/admin/discord/authorize/route.ts and
 * app/api/admin/discord/callback/route.ts.
 *
 * This is a SEPARATE credential from the bot token used everywhere else in
 * lib/discord.ts: the bot token authenticates the platform's own bot user for
 * REST calls (create channel, post message, …); this client id/secret pair
 * authenticates the Nxeon Discord APPLICATION to run a normal user-consent
 * OAuth flow so a staff member can prove "this Discord account is mine".
 * Same Discord application, two different credential types — see Discord's
 * own developer portal, which lists both under one app.
 *
 * Nxeon is a confidential (server-side) client, so this is the plain
 * Authorization Code flow with a client secret — no PKCE needed (PKCE exists
 * for clients that CAN'T keep a secret; we can). Discord's token endpoint
 * accepts client_secret_post (credentials in the form body), which is what's
 * used below.
 *
 * ── STATE / CSRF ─────────────────────────────────────────────────────────
 * Rather than stash `state` server-side (a cookie, a DB row) the way
 * lib/cloudflare-oauth.ts's flow does, `state` here IS a short-lived signed
 * JWT (via `jose`, the same library and secret — AUTH_SECRET — lib/auth.ts's
 * session cookie uses) embedding the initiating staff user's id and a
 * distinguishing `typ` claim. Discord round-trips `state` verbatim, so:
 *   - Signature + expiry verification is real CSRF protection: an attacker
 *     cannot forge or replay an old value without AUTH_SECRET.
 *   - No server-side storage is needed at all (no cookie to lose across a
 *     redirect, no DB row to clean up).
 *   - It's a pure, deterministic function — easy to unit test without a
 *     cookie jar or DB (see test/discord-oauth-state.test.ts).
 * CRITICAL: `state` is CSRF protection ONLY. The callback route re-derives
 * the actual signed-in user from the real session (`requireArea("support")`)
 * and only uses the state's embedded uid to CONFIRM it matches — never as the
 * source of truth for whose account gets linked. See the callback route's
 * top-of-file comment.
 */

import { SignJWT, jwtVerify } from "jose";
import { discordApplicationId, discordClientSecret } from "./discord";

const secret = new TextEncoder().encode(process.env.AUTH_SECRET!);

/** Distinguishes this JWT from a session/impersonation token signed with the same secret. */
const STATE_TYP = "discord_oauth_state";

/** How long a "Connect Discord" attempt has to complete consent. */
const STATE_TTL = "10m";

const DISCORD_OAUTH_AUTHORIZE_URL = "https://discord.com/oauth2/authorize";
const DISCORD_OAUTH_TOKEN_URL = "https://discord.com/api/v10/oauth2/token";
const DISCORD_API_USERS_ME = "https://discord.com/api/v10/users/@me";

/** Must exactly match the redirect URI registered on the Discord application. */
export function discordOauthRedirectUri(): string {
  const base = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
  return `${base}/api/admin/discord/callback`;
}

// ---------------------------------------------------------------------------
// State (CSRF) — sign / verify
// ---------------------------------------------------------------------------

/** Mint a fresh `state` value bound to the staff user starting the flow. */
export async function signDiscordOauthState(uid: string): Promise<string> {
  return new SignJWT({ typ: STATE_TYP })
    .setProtectedHeader({ alg: "HS256" })
    .setSubject(uid)
    .setIssuedAt()
    .setExpirationTime(STATE_TTL)
    .sign(secret);
}

export type StateCheck = { ok: true } | { ok: false; error: string };

/**
 * Verify a `state` value round-tripped from Discord. Checks signature,
 * expiry, the `typ` claim (so a session/impersonation cookie value can never
 * be replayed here even though it shares a secret), AND that the embedded
 * uid matches the user CURRENTLY signed in at callback time — binding the
 * flow to one continuous session, not just "signed by us at some point".
 *
 * Never throws — every failure mode (missing, malformed, expired, wrong
 * signature, wrong user) returns `{ ok: false, error }` with a message safe
 * to show the staff member.
 */
export async function verifyDiscordOauthState(state: string | null | undefined, expectedUid: string): Promise<StateCheck> {
  if (!state) return { ok: false, error: "Missing state — please start the connection again." };
  try {
    const { payload } = await jwtVerify(state, secret);
    if (payload.typ !== STATE_TYP) {
      return { ok: false, error: "Invalid state — please start the connection again." };
    }
    if (payload.sub !== expectedUid) {
      return {
        ok: false,
        error: "This Discord sign-in was started by a different account. Please try again.",
      };
    }
    return { ok: true };
  } catch {
    // jose throws for a bad signature, malformed token, AND an expired token
    // (JWTExpired) — all three collapse to the same user-facing message.
    return { ok: false, error: "That Discord sign-in link expired or was tampered with. Please try again." };
  }
}

// ---------------------------------------------------------------------------
// Authorization request
// ---------------------------------------------------------------------------

export async function discordOauthConfigured(): Promise<boolean> {
  const [appId, secret] = await Promise.all([discordApplicationId(), discordClientSecret()]);
  return Boolean(appId && secret);
}

/** Build the Discord consent URL for this connection attempt. `identify` is the only scope needed — just the account id + username. */
export async function discordAuthorizeUrl(state: string): Promise<string> {
  const clientId = await discordApplicationId();
  const url = new URL(DISCORD_OAUTH_AUTHORIZE_URL);
  url.searchParams.set("client_id", clientId);
  url.searchParams.set("redirect_uri", discordOauthRedirectUri());
  url.searchParams.set("response_type", "code");
  url.searchParams.set("scope", "identify");
  url.searchParams.set("state", state);
  // Force account chooser every time rather than silently reusing a stale
  // Discord session — this is an identity proof, not a "keep me logged in".
  url.searchParams.set("prompt", "consent");
  return url.toString();
}

// ---------------------------------------------------------------------------
// Token endpoint
// ---------------------------------------------------------------------------

type TokenResponse = {
  access_token?: string;
  token_type?: string;
  scope?: string;
  error?: string;
  error_description?: string;
};

/**
 * Exchange an authorization code for an access token. Returns `{ error }`
 * (never throws) for a network failure or any error Discord's token endpoint
 * reports, so callers can show a friendly message instead of crashing.
 */
export async function discordExchangeCode(code: string): Promise<{ accessToken?: string; error?: string }> {
  const clientId = await discordApplicationId();
  const clientSecret = await discordClientSecret();
  if (!clientId || !clientSecret) {
    return { error: "Discord sign-in isn't fully configured on this server yet." };
  }

  const params = new URLSearchParams({
    client_id: clientId,
    client_secret: clientSecret,
    grant_type: "authorization_code",
    code,
    redirect_uri: discordOauthRedirectUri(),
  });

  let res: Response;
  try {
    res = await fetch(DISCORD_OAUTH_TOKEN_URL, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded", Accept: "application/json" },
      body: params.toString(),
      cache: "no-store",
    });
  } catch {
    return { error: "Couldn't reach Discord to finish connecting. Try again shortly." };
  }

  let parsed: TokenResponse | null = null;
  try {
    parsed = (await res.json()) as TokenResponse;
  } catch {
    parsed = null;
  }

  if (!res.ok || !parsed?.access_token) {
    const detail = parsed?.error_description || parsed?.error || `HTTP ${res.status}`;
    return { error: `Discord rejected the connection (${String(detail).slice(0, 160)}).` };
  }

  return { accessToken: parsed.access_token };
}

// ---------------------------------------------------------------------------
// Identify
// ---------------------------------------------------------------------------

export type DiscordSelfUser = { id: string; username: string };

/** GET /users/@me with the just-obtained access token — the real Discord user id + username. */
export async function fetchDiscordSelf(accessToken: string): Promise<{ user?: DiscordSelfUser; error?: string }> {
  let res: Response;
  try {
    res = await fetch(DISCORD_API_USERS_ME, {
      headers: { Authorization: `Bearer ${accessToken}` },
      cache: "no-store",
    });
  } catch {
    return { error: "Couldn't reach Discord to confirm your account. Try again shortly." };
  }
  if (!res.ok) {
    return { error: `Discord rejected the account lookup (HTTP ${res.status}).` };
  }
  let json: { id?: unknown; username?: unknown } | null = null;
  try {
    json = await res.json();
  } catch {
    json = null;
  }
  if (!json || typeof json.id !== "string" || !json.id) {
    return { error: "Discord didn't return a usable account id." };
  }
  return { user: { id: json.id, username: typeof json.username === "string" ? json.username : "" } };
}

