"use server";

/**
 * Staff self-service Discord-account linking — the status query and the
 * "Disconnect" action for the Settings → Integrations "Discord account" card
 * (components/admin/DiscordIntegration.tsx). The "Connect" side of the flow
 * is a plain redirect to app/api/admin/discord/authorize/route.ts (a GET
 * route, not a server action, because it has to 302 to Discord).
 *
 * Every export here is a public network endpoint (see
 * lib/actions-support.ts's top-of-file comment on that exact property) — both
 * functions re-derive the real signed-in user via `requireArea("support")`
 * rather than trusting anything passed in, and neither accepts a userId
 * argument. Gated on the "support" area (not just `isStaff`) because that is
 * the SAME area lib/actions-chat.ts's `requireArea("support")` gates for
 * actually replying to a ticket/chat — a BILLING-role account could link a
 * Discord id here, but it would never be usable for a reply (see
 * lib/discord-bridge.ts's `resolveDiscordReplyActor`, which re-checks
 * `canAccess(role, "support")` independently at reply time). Keeping the
 * gates aligned just avoids a pointless "connected but can never use it" UI
 * state for BILLING/CUSTOMER accounts.
 */

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireArea } from "./rbac";
import { checkRateLimit } from "./rate-limit";
import { getDiscordUserById } from "./discord";
import { discordOauthConfigured, discordOauthRedirectUri } from "./discord-oauth";

export type DiscordLinkStatus = {
  connected: boolean;
  /** Best-effort display username — null if unlinked or the lookup failed/was skipped. */
  username: string | null;
  /** Is "Connect Discord" available in this environment (app id + client secret configured)? */
  oauthAvailable: boolean;
  /** Shown to an operator when oauthAvailable is false, so they know what to register. */
  redirectUri: string;
};

/** Connection state for the current staff member. Never returns anything sensitive. */
export async function getDiscordLinkStatus(): Promise<DiscordLinkStatus> {
  const me = await requireArea("support");
  const discordUserId = (me as unknown as { discordUserId?: string | null }).discordUserId ?? null;

  let username: string | null = null;
  if (discordUserId) {
    const profile = await getDiscordUserById(discordUserId).catch(() => null);
    username = profile?.username || null;
  }

  return {
    connected: Boolean(discordUserId),
    username,
    oauthAvailable: await discordOauthConfigured(),
    redirectUri: discordOauthRedirectUri(),
  };
}

/** Unlink the current staff member's Discord account. Idempotent — fine to call when already unlinked. */
export async function disconnectDiscordLink(): Promise<{ ok?: boolean; error?: string }> {
  const me = await requireArea("support");

  const rl = checkRateLimit(`discord-link-disconnect:${me.id}`, { max: 10, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };

  await db.user.update({ where: { id: me.id }, data: { discordUserId: null } as any });
  await db.auditLog
    .create({ data: { userId: me.id, action: "discord.unlink" } })
    .catch(() => {});

  revalidatePath("/dashboard/settings");
  return { ok: true };
}

