import { NextRequest, NextResponse } from "next/server";
import { requireArea } from "@/lib/rbac";
import { checkRateLimit } from "@/lib/rate-limit";
import { discordAuthorizeUrl, discordOauthConfigured, signDiscordOauthState } from "@/lib/discord-oauth";

export const dynamic = "force-dynamic";

const base = () => (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");

/**
 * Step 1 of "Connect Discord" (Settings → Integrations): start the staff
 * Discord-account-linking OAuth flow.
 *
 * `requireArea("support")` is the SAME gate lib/actions-chat.ts's
 * `replyToConversation` uses before writing a chat reply — the exact area
 * that governs whether a Discord-linked identity would ever actually be
 * usable to reply from Discord (see lib/discord-bridge.ts's
 * `resolveDiscordReplyActor`). A CUSTOMER-role account (or an unauthenticated
 * request) never reaches Discord's consent screen: `requireArea` redirects
 * to /login or /admin first.
 *
 * No server-side state storage is needed — `state` is itself a short-lived
 * signed JWT (see lib/discord-oauth.ts's top-of-file comment for why that's
 * real CSRF protection here).
 */
export async function GET(_req: NextRequest) {
  const me = await requireArea("support");

  const rl = checkRateLimit(`discord-oauth-start:${me.id}`, { max: 10, windowMs: 60_000 });
  if (!rl.ok) {
    return NextResponse.redirect(
      `${base()}/dashboard/settings?tab=integrations&discord=error&discordmsg=${encodeURIComponent(
        `Too many attempts — try again in ${rl.retryAfterSec}s.`,
      )}`,
    );
  }

  if (!(await discordOauthConfigured())) {
    return NextResponse.redirect(
      `${base()}/dashboard/settings?tab=integrations&discord=error&discordmsg=${encodeURIComponent(
        "Discord sign-in isn't set up on this server yet.",
      )}`,
    );
  }

  const state = await signDiscordOauthState(me.id);
  const authUrl = await discordAuthorizeUrl(state);
  return NextResponse.redirect(authUrl);
}

