import { discordExchangeCode, fetchDiscordSelf, verifyDiscordOauthState } from "@/lib/discord-oauth";

export const dynamic = "force-dynamic";

const base = () => (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");

const isUniqueConflict = (e: unknown): boolean => (e as { code?: string } | null)?.code === "P2002";

function redirectWith(params: Record<string, string>): NextResponse {
  const url = new URL(`${base()}/dashboard/settings`);
  url.searchParams.set("tab", "integrations");
  for (const [k, v] of Object.entries(params)) url.searchParams.set(k, v);
  return NextResponse.redirect(url.toString());
}

function fail(msg: string): NextResponse {
  return redirectWith({ discord: "error", discordmsg: msg });
}

/**
 * Step 2 of "Connect Discord": the OAuth redirect target. MUST live at
 * exactly `/api/admin/discord/callback` — that path is registered verbatim
 * as the redirect URI on the Discord application.
 *
 * IDENTITY, NOT JUST CSRF. Two separate things happen here and they must not
 * be conflated:
 *   1. `state` is checked (`verifyDiscordOauthState`) purely as CSRF
 *      protection — proof this callback corresponds to a request THIS
 *      server actually issued, recently, for the currently-signed-in user.
 *   2. The Nxeon identity that gets `discordUserId` written onto it is
 *      `requireArea("support")`'s return value — the REAL session, re-derived
 *      independently at callback time. Nothing about WHOSE account gets
 *      linked ever comes from the OAuth round-trip (the `code`, `state`, or
 *      anything Discord sends) — only Discord's own `/users/@me` response
 *      (after we independently obtained the access token with our own
 *      client secret) supplies the Discord-side id being linked.
 * Do not "simplify" this by trusting an id embedded in `state` for anything
 * beyond the equality check inside `verifyDiscordOauthState`.
 */
export async function GET(req: NextRequest) {
  const me = await requireArea("support");

  const sp = req.nextUrl.searchParams;

  // The staff member declined on Discord's consent screen (or Discord errored).
  const oauthError = sp.get("error");
  if (oauthError) {
    return fail(
      oauthError === "access_denied"
        ? "Discord connection cancelled."
        : `Discord returned an error (${oauthError.slice(0, 60)}).`,
    );
  }

  const state = sp.get("state");
  const stateCheck = await verifyDiscordOauthState(state, me.id);
  if (!stateCheck.ok) return fail(stateCheck.error);

  const code = sp.get("code");
  if (!code) return fail("Discord didn't return an authorization code. Please try connecting again.");

  const exchanged = await discordExchangeCode(code);
  if (!exchanged.accessToken) {
    return fail(exchanged.error ?? "Couldn't complete the Discord connection. Please try again.");
  }

  const identified = await fetchDiscordSelf(exchanged.accessToken);
  if (!identified.user) {
    return fail(identified.error ?? "Couldn't confirm your Discord account. Please try again.");
  }

  try {
    await db.user.update({
      where: { id: me.id },
      data: { discordUserId: identified.user.id } as any,
    });
  } catch (e) {
    if (isUniqueConflict(e)) {
      return fail("This Discord account is already linked to another Nxeon staff account.");
    }
    console.error("[discord-oauth] failed to store discordUserId for", me.id, e);
    return fail("Couldn't save the Discord connection right now. Please try again shortly.");
  }

  await db.auditLog
    .create({ data: { userId: me.id, action: "discord.link", detail: identified.user.username || identified.user.id } })
    .catch(() => {});

  return redirectWith({ discord: "connected" });
}

