"use client";

import { useEffect, useState, useTransition } from "react";
import { Badge } from "@/components/ui/primitives";
import { disconnectDiscordLink } from "@/lib/actions-discord-link";

/**
 * Settings → Integrations "Discord account" card — staff-only self-service
 * linking for the Discord support bridge's reply-attribution
 * (lib/discord-bridge.ts's `resolveDiscordReplyActor`). Only rendered for
 * staff roles (see app/dashboard/settings/page.tsx) — a CUSTOMER-role user
 * would hit a redirect from the authorize route even if this somehow rendered
 * for them, but there's no reason to show it to them at all.
 */
export function DiscordIntegration({
  connected: initialConnected,
  username: initialUsername,
  oauthAvailable,
  redirectUri,
}: {
  connected: boolean;
  username: string | null;
  oauthAvailable: boolean;
  redirectUri: string;
}) {
  const [connected, setConnected] = useState(initialConnected);
  const [username, setUsername] = useState(initialUsername);
  const [error, setError] = useState<string | null>(null);
  const [status, setStatus] = useState<string | null>(null);
  const [pending, start] = useTransition();

  // Read the one-shot ?discord=connected|error&discordmsg=… flags the OAuth
  // callback redirects back with, then scrub them from the address bar so a
  // refresh doesn't re-show the banner.
  useEffect(() => {
    const sp = new URLSearchParams(window.location.search);
    const result = sp.get("discord");
    const msg = sp.get("discordmsg");
    if (!result) return;

    if (result === "connected") {
      setConnected(true);
      setStatus("Discord connected. Replies you send from Discord will now be attributed to you.");
    } else if (result === "error") {
      setError(msg || "Couldn't connect Discord.");
    }

    ["discord", "discordmsg"].forEach((k) => sp.delete(k));
    const qs = sp.toString();
    window.history.replaceState({}, "", `${window.location.pathname}${qs ? `?${qs}` : ""}`);
  }, []);

  function disconnect() {
    setError(null);
    setStatus(null);
    start(async () => {
      const res = await disconnectDiscordLink();
      if (res?.error) setError(res.error);
      else {
        setConnected(false);
        setUsername(null);
        setStatus("Discord disconnected. Replies from Discord will no longer be attributed to you until you reconnect.");
      }
    });
  }

  return (
    <div className="card">
      <div className="mb-1 flex flex-wrap items-center justify-between gap-2">
        <h2 className="font-semibold">Discord account</h2>
        {connected ? (
          <Badge tone="green">Connected{username ? ` as ${username}` : ""}</Badge>
        ) : (
          <Badge tone="slate">Not connected</Badge>
        )}
      </div>

      <p className="mb-4 text-sm text-slate-400">
        Link your Discord account so replies you send from the support bridge (clicking Reply on a
        mirrored ticket or chat message) are correctly attributed to you, not to a shared identity.
        We only ask to confirm your Discord account id and username — we never post as you or read
        your Discord messages.
      </p>

      {error && (
        <div className="mb-3 rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
          {error}
        </div>
      )}
      {status && (
        <div className="mb-3 rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">
          {status}
        </div>
      )}

      {connected ? (
        <div className="flex flex-wrap items-center gap-3">
          <button className="btn-secondary py-1.5 text-sm" onClick={disconnect} disabled={pending}>
            {pending ? "Disconnecting…" : "Disconnect Discord"}
          </button>
          <span className="text-xs text-slate-500">
            You won&apos;t be able to reply from Discord until you reconnect.
          </span>
        </div>
      ) : oauthAvailable ? (
        <a href="/api/admin/discord/authorize" className="btn-secondary inline-block py-1.5 text-sm">
          Connect Discord
        </a>
      ) : (
        <p className="text-[11px] text-slate-600">
          Operator note: set the <span className="font-mono">discord_client_secret</span> setting
          (encrypted, same as <span className="font-mono">discord_bot_token</span>) and confirm{" "}
          <span className="font-mono">{redirectUri}</span> is registered as an OAuth2 redirect on the
          Discord application, to enable one-click connect.
        </p>
      )}
    </div>
  );
}

