// The state-signing helpers derive their key from AUTH_SECRET at import time
// (mirroring lib/auth.ts) — set a deterministic one before importing.
process.env.AUTH_SECRET = process.env.AUTH_SECRET || "test-secret-for-discord-oauth";

import { test } from "node:test";
import assert from "node:assert/strict";
import { SignJWT } from "jose";
import { signDiscordOauthState, verifyDiscordOauthState } from "../lib/discord-oauth.ts";

/**
 * CSRF protection for the staff Discord-account-linking flow
 * (app/api/admin/discord/authorize + callback/route.ts) rests entirely on
 * `state` being a short-lived, signed, uid-bound JWT rather than a bare
 * random string — see lib/discord-oauth.ts's top-of-file comment. This suite
 * exercises the real sign/verify pair against real `jose` primitives (no
 * network, no DB — `signDiscordOauthState`/`verifyDiscordOauthState` are pure
 * functions of their arguments and the AUTH_SECRET env var).
 */

test("a freshly minted state verifies for the SAME uid that requested it", async () => {
  const state = await signDiscordOauthState("user_123");
  const result = await verifyDiscordOauthState(state, "user_123");
  assert.equal(result.ok, true);
});

test("a state minted for one uid is rejected when checked against a different uid", async () => {
  // This is the actual CSRF-relevant case: an attacker who captures/replays a
  // `state` value cannot use it against a session belonging to someone else,
  // because the callback re-derives the real signed-in user independently and
  // only ACCEPTS a match — see app/api/admin/discord/callback/route.ts.
  const state = await signDiscordOauthState("user_123");
  const result = await verifyDiscordOauthState(state, "user_456");
  assert.equal(result.ok, false);
  if (!result.ok) assert.match(result.error, /different account/i);
});

test("a missing state is rejected with a clear message, not a crash", async () => {
  const result = await verifyDiscordOauthState(null, "user_123");
  assert.equal(result.ok, false);
  if (!result.ok) assert.match(result.error, /missing/i);

  const result2 = await verifyDiscordOauthState(undefined, "user_123");
  assert.equal(result2.ok, false);

  const result3 = await verifyDiscordOauthState("", "user_123");
  assert.equal(result3.ok, false);
});

test("a tampered state (bad signature) is rejected", async () => {
  const state = await signDiscordOauthState("user_123");
  // Flip a character in the signature segment (the part after the last dot).
  const parts = state.split(".");
  const tamperedSig = parts[2].slice(0, -4) + (parts[2].slice(-4) === "aaaa" ? "bbbb" : "aaaa");
  const tampered = [parts[0], parts[1], tamperedSig].join(".");

  const result = await verifyDiscordOauthState(tampered, "user_123");
  assert.equal(result.ok, false);
});

test("a state signed with a DIFFERENT secret is rejected", async () => {
  // Simulates a forged token an attacker minted themselves without knowing
  // AUTH_SECRET.
  const forgedSecret = new TextEncoder().encode("attacker-does-not-know-this");
  const forged = await new SignJWT({ typ: "discord_oauth_state" })
    .setProtectedHeader({ alg: "HS256" })
    .setSubject("user_123")
    .setIssuedAt()
    .setExpirationTime("10m")
    .sign(forgedSecret);

  const result = await verifyDiscordOauthState(forged, "user_123");
  assert.equal(result.ok, false);
});

test("an expired state is rejected", async () => {
  const secret = new TextEncoder().encode(process.env.AUTH_SECRET!);
  const expired = await new SignJWT({ typ: "discord_oauth_state" })
    .setProtectedHeader({ alg: "HS256" })
    .setSubject("user_123")
    .setIssuedAt(Math.floor(Date.now() / 1000) - 3600)
    .setExpirationTime(Math.floor(Date.now() / 1000) - 1800) // expired 30 minutes ago
    .sign(secret);

  const result = await verifyDiscordOauthState(expired, "user_123");
  assert.equal(result.ok, false);
  if (!result.ok) assert.match(result.error, /expired/i);
});

test("a token of the WRONG kind (e.g. a session token shape) signed with the same secret is rejected", async () => {
  // Same secret, same signing algorithm, but missing/wrong `typ` — proves the
  // `typ` claim actually gates verification rather than being decorative,
  // mirroring lib/auth.ts's own session-vs-impersonation `typ` discipline.
  const secret = new TextEncoder().encode(process.env.AUTH_SECRET!);
  const sessionShaped = await new SignJWT({ sub: "user_123", sv: 0, typ: "session" })
    .setProtectedHeader({ alg: "HS256" })
    .setIssuedAt()
    .setExpirationTime("30d")
    .sign(secret);

  const result = await verifyDiscordOauthState(sessionShaped, "user_123");
  assert.equal(result.ok, false);
});

test("a garbage string is rejected without throwing", async () => {
  await assert.doesNotReject(async () => {
    const result = await verifyDiscordOauthState("not.a.jwt", "user_123");
    assert.equal(result.ok, false);
  });
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { resolveDiscordReplyActor } from "../lib/discord-bridge.ts";
import { extractInteractionUserId } from "../lib/discord.ts";

/**
 * The 2026-08-30 rework replaces a single hardcoded `discord_reply_as_user_id`
 * with real per-Discord-user attribution: `resolveDiscordReplyActor` decides
 * WHO a Discord-originated reply is attributed to, given the
 * `User.findUnique({ where: { discordUserId } })` lookup result.
 * `extractInteractionUserId` decides WHICH Discord user id that lookup even
 * uses, from Discord's (already signature-verified) interaction payload.
 *
 * Both are pure functions — no DB, no network — so this suite feeds them
 * synthetic inputs directly rather than exercising the live database.
 */

// ---------------------------------------------------------------------------
// resolveDiscordReplyActor
// ---------------------------------------------------------------------------

test("a Discord id linked to a SUPPORT staff account resolves to that user", () => {
  const result = resolveDiscordReplyActor({ id: "u_support_1", role: "SUPPORT" as any });
  assert.deepEqual(result, { actorId: "u_support_1" });
});

test("a Discord id linked to an ADMIN account resolves to that user", () => {
  const result = resolveDiscordReplyActor({ id: "u_admin_1", role: "ADMIN" as any });
  assert.deepEqual(result, { actorId: "u_admin_1" });
});

test("no linked account (null lookup) is rejected with a clear message, not a silent fallback", () => {
  const result = resolveDiscordReplyActor(null);
  assert.ok("error" in result, "must be a rejection, not an actorId");
  if ("error" in result) {
    assert.match(result.error, /isn't linked/i);
    assert.match(result.error, /dashboard\/settings/, "must point at the real linking UI, not a dead end");
  }
});

test("a linked account WITHOUT support access (e.g. BILLING, or demoted CUSTOMER) is rejected, not attributed", () => {
  // This is the "since-demoted staff member" case from the spec: the Discord
  // account is still linked, but the Nxeon role no longer has support access.
  const billing = resolveDiscordReplyActor({ id: "u_billing_1", role: "BILLING" as any });
  assert.ok("error" in billing);

  const customer = resolveDiscordReplyActor({ id: "u_former_staff", role: "CUSTOMER" as any });
  assert.ok("error" in customer);
});

test("there is no fallback to any other identity — every rejection path returns the same explicit message shape", () => {
  const a = resolveDiscordReplyActor(null);
  const b = resolveDiscordReplyActor({ id: "x", role: "CUSTOMER" as any });
  assert.ok("error" in a && "error" in b);
  // Same message for "not linked" and "linked but no longer staff" — neither
  // one ever produces an actorId.
  assert.equal(a.error, b.error);
});

// ---------------------------------------------------------------------------
// extractInteractionUserId
// ---------------------------------------------------------------------------

test("extracts the real Discord user id from a guild interaction's member.user.id (the shape this bridge always gets)", () => {
  const interaction = { member: { user: { id: "111222333" } } };
  assert.equal(extractInteractionUserId(interaction), "111222333");
});

test("falls back to top-level user.id for a DM-shaped interaction", () => {
  const interaction = { user: { id: "999888777" } };
  assert.equal(extractInteractionUserId(interaction), "999888777");
});

test("prefers member.user.id over a top-level user.id when both are somehow present", () => {
  const interaction = { member: { user: { id: "aaa" } }, user: { id: "bbb" } };
  assert.equal(extractInteractionUserId(interaction), "aaa");
});

test("returns null (never throws) for a malformed or empty interaction payload", () => {
  assert.equal(extractInteractionUserId({}), null);
  assert.equal(extractInteractionUserId(null), null);
  assert.equal(extractInteractionUserId(undefined), null);
  assert.equal(extractInteractionUserId({ member: {} }), null);
  assert.equal(extractInteractionUserId({ member: { user: {} } }), null);
  assert.equal(extractInteractionUserId({ member: { user: { id: 12345 } } }), null, "a non-string id must not be trusted");
  assert.equal(extractInteractionUserId("not an object"), null);
});

