import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { stripComments } from "./_source-tools.ts";

/**
 * Structural guards over the staff Discord-account-linking OAuth routes
 * (app/api/admin/discord/authorize + callback/route.ts).
 *
 * These assert the two security properties the spec calls out explicitly:
 *   1. Only staff who can reach the "support" area may start/complete the
 *      flow (a CUSTOMER must never be able to link a Discord identity).
 *   2. The callback writes `discordUserId` onto the REAL signed-in user
 *      re-derived from the session at callback time — never onto an id taken
 *      from the OAuth round-trip itself (`state`'s subject is checked for
 *      EQUALITY against that real user, never used as the write target).
 *
 * Source-based (no route import, no DB, no network) — importing the route
 * would pull in Prisma and open a connection to the production database, the
 * same reasoning test/api-http-surface.test.ts documents for this repo.
 */

function readSrc(rel: string): string {
  return stripComments(readFileSync(fileURLToPath(new URL(rel, import.meta.url)), "utf8"));
}

const AUTHORIZE = readSrc("../app/api/admin/discord/authorize/route.ts");
const CALLBACK = readSrc("../app/api/admin/discord/callback/route.ts");

test("the authorize route requires support-area staff before minting any state", () => {
  const guardIdx = AUTHORIZE.indexOf('requireArea("support")');
  const stateIdx = AUTHORIZE.indexOf("signDiscordOauthState(");
  assert.ok(guardIdx >= 0, "must gate on requireArea(\"support\")");
  assert.ok(stateIdx >= 0, "must mint a state");
  assert.ok(guardIdx < stateIdx, "the staff gate must run BEFORE a state is minted");
});

test("the callback route requires support-area staff independently of the OAuth round-trip", () => {
  const guardIdx = CALLBACK.indexOf('requireArea("support")');
  assert.ok(guardIdx >= 0, "must re-derive the real signed-in user via requireArea(\"support\")");
  // Must happen before the state/code are even read, so an unauthenticated
  // request never gets far enough to consume a valid code.
  const stateReadIdx = CALLBACK.indexOf('sp.get("state")');
  assert.ok(stateReadIdx >= 0);
  assert.ok(guardIdx < stateReadIdx, "the real-session check must run before touching the OAuth params");
});

test("the callback verifies state against the REAL session user's id, not a value from the OAuth round-trip", () => {
  assert.match(
    CALLBACK,
    /verifyDiscordOauthState\(\s*state\s*,\s*me\.id\s*\)/,
    "state must be checked against `me.id` (the independently re-derived session user)",
  );
});

test("the callback writes discordUserId keyed on the real session user's id (me.id), never on anything from the OAuth params", () => {
  const updateCall = /db\.user\.update\(\{[\s\S]*?\}\);/.exec(CALLBACK)?.[0] ?? "";
  assert.ok(updateCall, "found the discordUserId write");
  assert.match(updateCall, /where:\s*\{\s*id:\s*me\.id\s*\}/, "must target the real session user's row");
  assert.match(
    updateCall,
    /discordUserId:\s*identified\.user\.id/,
    "the value written must come from Discord's own /users/@me response (identified.user.id), not from `state` or `code`",
  );
  // Negative check: the write must not reference `state` at all — proves the
  // OAuth round-trip cannot influence WHICH Nxeon row gets linked.
  assert.ok(!/state/.test(updateCall), "the write itself must not reference `state` in any form");
});

test("the callback treats a unique-constraint conflict (P2002) as a friendly 'already linked' error, not a raw crash", () => {
  assert.match(CALLBACK, /code.*===.*["']P2002["']|isUniqueConflict/);
  assert.match(CALLBACK, /already linked to another/i);
});

test("both routes are dynamic (never statically cached) — an OAuth redirect must not be served from cache", () => {
  assert.match(AUTHORIZE, /export const dynamic = ["']force-dynamic["']/);
  assert.match(CALLBACK, /export const dynamic = ["']force-dynamic["']/);
});

